CREATE TABLE IF NOT EXISTS "users" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"userId" UUID NOT NULL UNIQUE,
	"name" VARCHAR(255) NOT NULL,
	"email" VARCHAR(255) NOT NULL UNIQUE,
	"password" TEXT NOT NULL UNIQUE,
	"createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"lastLogin" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"role" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "products" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"productId" UUID NOT NULL UNIQUE,
	"ownerId" UUID NOT NULL,
	"name" TEXT NOT NULL,
	"price" BIGINT NOT NULL,
	"type" TEXT NOT NULL,
	"item" TEXT,
	"quantity" INT NOT NULL,
	"createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "cart" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"ownerId" UUID NOT NULL UNIQUE,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "cartProducts" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "cartId" INTEGER NOT NULL,
    "productId" UUID NOT NULL,
    "quantity" INTEGER NOT NULL DEFAULT 1 CHECK ("quantity" > 0),

    PRIMARY KEY("id"),

    UNIQUE ("cartId", "productId"),

    FOREIGN KEY ("cartId")
        REFERENCES "cart"("id")
        ON UPDATE NO ACTION
        ON DELETE CASCADE,

    FOREIGN KEY ("productId")
        REFERENCES "products"("productId")
        ON UPDATE NO ACTION
        ON DELETE NO ACTION
);

CREATE TABLE IF NOT EXISTS "trasactions" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"transactionId" UUID NOT NULL UNIQUE,
	"externalId" TEXT NOT NULL UNIQUE,
	"userId" UUID NOT NULL,
	"amount" BIGINT,
	"status" TEXT,
	"createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"finishedAt" TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "transaction_items" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"productId" UUID NOT NULL,
	"transactionId" UUID NOT NULL,
	"name" TEXT NOT NULL,
	"price" BIGINT NOT NULL,
	"type" TEXT NOT NULL,
	"item" TEXT,
	"createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

ALTER TABLE "products"
ADD FOREIGN KEY("ownerId") REFERENCES "users"("userId")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "cart"
ADD FOREIGN KEY("ownerId") REFERENCES "users"("userId")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "cart"
ADD FOREIGN KEY("products") REFERENCES "products"("productId")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "trasactions"
ADD FOREIGN KEY("userId") REFERENCES "users"("userId")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "transaction_items"
ADD FOREIGN KEY("productId") REFERENCES "products"("productId")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "transaction_items"
ADD FOREIGN KEY("transactionId") REFERENCES "trasactions"("transactionId")
ON UPDATE NO ACTION ON DELETE NO ACTION;